/** Isolated persistence with synthetic model replies; no live model or HTTP calls. */
@SpringBootTest(properties={"spring.jpa.hibernate.ddl-auto=create-drop","spring.flyway.enabled=false","consense.llm.enabled=false","consense.ocr.enabled=false","consense.vector.provider=memory"})
@ActiveProfiles("h2")
class DraftSavedGroupResumeTest {
    @DynamicPropertySource static void db(DynamicPropertyRegistry registry){registry.add("spring.datasource.url",()->"jdbc:h2:mem:saved_group_resume;MODE=MySQL;DATABASE_TO_LOWER=TRUE;DB_CLOSE_DELAY=-1;DB_CLOSE_ON_EXIT=FALSE");}
    @Autowired DraftAutomationService service;
    @Autowired DraftAutomationRunRepository runs;
    @Autowired DraftAutomationItemRepository items;
    @Autowired DraftTemplateGraphHeadRepository heads;
    @Autowired ProjectRepository projects;
    @MockBean DraftTemplateGraphService graphs;
    @MockBean AiGateway ai;
    @MockBean LlmProfiles profiles;
    LlmOperation operation;LlmProfiles localProfiles;String project,id,oldRaw;DraftAutomationItem oldGroup;

    @BeforeEach void setup(){
        com.consense.config.ConsenseProperties settings=new com.consense.config.ConsenseProperties();settings.getLlm().setEnabled(true);settings.getLlm().setBaseUrl("http://synthetic.invalid");settings.getLlm().setChatModel("synthetic");localProfiles=new LlmProfiles(settings,mock(LlmClient.class),null);operation=localProfiles.resolve("local");when(profiles.resolve("local")).thenReturn(operation);when(profiles.bind(any())).thenAnswer(call->localProfiles.bind(call.getArgument(0)));service.groupConcurrency(1);service.acceptanceProbeStopOnDefect(true);
        project="resume-"+UUID.randomUUID();Project p=new Project();p.setId(project);p.setNameZhHans("Synthetic continuation");projects.save(p);DraftTemplateGraphHead head=new DraftTemplateGraphHead();head.setProjectId(project);head.setDraftRevisionId("saved-result");heads.saveAndFlush(head);
        List<JsonNode> readings=Arrays.asList(source("1"),source("2"));DraftAutomaticDiscovery.Plan plan=DraftAutomaticDiscovery.plan(readings);List<Map<String,Object>> groups=DraftAutomaticDiscovery.planGroups(plan);Map<String,Object> manifest=obj("execution","fixed-root-groups-v1","plan",plan.descriptor(),"groups",groups,"concurrency",1,"firstProbeFailure",obj("taskId",groups.get(0).get("taskId"),"reasons",Collections.singletonList("historic-stop")));
        DraftAutomationRun run=new DraftAutomationRun();id=UUID.randomUUID().toString();run.setId(id);run.setProjectId(project);run.setProfileId("local");run.setConfigurationSha256(operation.getIdentity().getConfigurationSha256());run.setStatus("PARTIAL");run.setPhase("READY_FOR_REVIEW");run.setResultRevisionId("saved-result");run.setSourceStampJson("[]");run.setManifestJson(JsonUtils.write(manifest));run.setCreatedAt(Instant.now());run.setUpdatedAt(run.getCreatedAt());run.setCancelRequested(true);runs.saveAndFlush(run);
        Map<String,Object> child=new LinkedHashMap<>(plan.tasks().get(0));child.putAll(obj("status","partial","nodes",Collections.emptyList(),"requirements",Collections.emptyList(),"issues",Collections.singletonList(obj("reason","historic-review")),"modelCalls",0));item(plan.tasks().get(0),0,"DONE",child);item(plan.tasks().get(1),1,"PENDING",null);
        Map<String,Object> receipt=new LinkedHashMap<>(groups.get(0));receipt.putAll(obj("status","partial","rawResponse","ORIGINAL_RAW_MUST_NOT_CHANGE","modelCalls",1,"stopReasons",Collections.singletonList("historic-stop")));oldGroup=item(groups.get(0),2,"DONE",receipt);oldRaw=oldGroup.getReceiptJson();item(groups.get(1),3,"PENDING",null);
        when(graphs.automationInput(eq(project),isNull(),eq("saved-result"),isNull(),anyList())).thenAnswer(call->{((List<JsonNode>)call.getArgument(4)).addAll(readings);return obj("graph",obj("variables",new ArrayList<>(),"events",new ArrayList<>()),"sources",new ArrayList<>());});when(graphs.save(eq(project),anyMap(),isNull(),eq("saved-result"),eq(true))).thenReturn(Collections.singletonMap("id","continued-result"));
        when(ai.complete(anyString(),anyString())).thenAnswer(call->{JsonNode packet=JsonUtils.parse(call.getArgument(1));List<Object> outcomes=new ArrayList<>();for(JsonNode instruction:packet.path("instructions"))outcomes.add(obj("sourceTaskId",instruction.path("sourceTaskId").asText(),"status","no_requirement","reason","Synthetic source reviewed"));return JsonUtils.write(obj("nodes",Collections.emptyList(),"requirements",Collections.emptyList(),"scopeRules",Collections.emptyList(),"taskOutcomes",outcomes,"notes",Collections.emptyList()));});
    }

    @Test void savedPartialDispatchesOnlyPendingGroupAndKeepsHistoricFailure(){
        assertEquals(true,service.get(project,id).get("canContinueSavedGroups"));service.resume(project,id,null,"saved-result");Map<String,Object> result=await();assertEquals("continued-result",result.get("resultRevisionId"));assertEquals("PARTIAL",result.get("status"));assertFalse(String.valueOf(result.get("message")).contains("historic-stop"));verify(ai,times(1)).complete(anyString(),anyString());assertEquals(oldRaw,items.findById(oldGroup.getId()).get().getReceiptJson());
        JsonNode manifest=JsonUtils.parse(runs.findById(id).get().getManifestJson());assertEquals("historic-stop",manifest.path("firstProbeFailure").path("reasons").path(0).asText());assertFalse(manifest.has("continuation"));assertEquals("continued-result",manifest.path("lastContinuation").path("resultRevisionId").asText());
    }

    @Test void returnedButUnsavedDeltaIsSavedOnResumeWithoutAnotherCall(){
        Map<String,Object> charged=JsonUtils.readMap(oldRaw);charged.put("modelCalls",767);oldGroup.setReceiptJson(JsonUtils.write(charged));items.saveAndFlush(oldGroup);oldRaw=oldGroup.getReceiptJson();
        when(graphs.save(eq(project),anyMap(),isNull(),eq("saved-result"),eq(true))).thenThrow(new IllegalStateException("synthetic save interruption")).thenReturn(Collections.singletonMap("id","continued-result"));service.resume(project,id,null,"saved-result");assertEquals("saved-result",await().get("resultRevisionId"));assertFalse(DraftAutomationService.continuationTasks(runs.findById(id).get().getManifestJson()).isEmpty());assertEquals(true,service.get(project,id).get("canContinueSavedGroups"));
        service.resume(project,id,null,"saved-result");assertEquals("continued-result",await().get("resultRevisionId"));verify(ai,times(1)).complete(anyString(),anyString());assertEquals(oldRaw,items.findById(oldGroup.getId()).get().getReceiptJson());
    }

    @Test void committedProbeStopRecoversAsPartialButAnOlderStopCannotOverrideUserCancellation(){
        DraftAutomationRun row=runs.findById(id).get();Map<String,Object> manifest=JsonUtils.readMap(row.getManifestJson());manifest.put("lastContinuation",obj("resultRevisionId","saved-result","stop",obj("reasons",Collections.singletonList("new-probe"))));row.setManifestJson(JsonUtils.write(manifest));assertTrue(DraftAutomationService.continuationProbeStop(row));
        manifest.put("continuation",obj("baseResultRevisionId","saved-result","taskIds",Collections.singletonList("new-pending")));row.setManifestJson(JsonUtils.write(manifest));assertFalse(DraftAutomationService.continuationProbeStop(row),"A live cycle without a probe stop may have been explicitly cancelled");
        manifest.remove("continuation");row.setResultRevisionId("different-result");row.setManifestJson(JsonUtils.write(manifest));assertFalse(DraftAutomationService.continuationProbeStop(row));
    }

    @Test void originalLifetimeAndChangedHeadRejectBeforeModelDispatch(){
        assertThrows(RuntimeException.class,()->service.resume(project,id,null,"newer-head"));DraftAutomationRun row=runs.findById(id).get();row.setCreatedAt(Instant.now().minusSeconds(21601));runs.saveAndFlush(row);assertEquals(false,service.get(project,id).get("canContinueSavedGroups"));assertThrows(RuntimeException.class,()->service.resume(project,id,null,"saved-result"));verifyNoInteractions(ai);
    }

    @Test void unknownGroupIsNotReplayedAndItsReservedCallsStillConsumeTheBudget(){
        Map<String,Object> receipt=JsonUtils.readMap(oldRaw);receipt.put("status","unknown");receipt.put("modelCalls",null);receipt.put("reservedModelCalls",768);oldGroup.setStatus("UNKNOWN");oldGroup.setReceiptJson(JsonUtils.write(receipt));items.saveAndFlush(oldGroup);
        assertThrows(RuntimeException.class,()->service.resume(project,id,null,"saved-result"));verifyNoInteractions(ai);assertEquals("UNKNOWN",items.findById(oldGroup.getId()).get().getStatus());
        receipt.put("reservedModelCalls",3);oldGroup.setReceiptJson(JsonUtils.write(receipt));items.saveAndFlush(oldGroup);String unknown=oldGroup.getReceiptJson();service.resume(project,id,null,"saved-result");await();verify(ai,times(1)).complete(anyString(),anyString());assertEquals(unknown,items.findById(oldGroup.getId()).get().getReceiptJson());
    }

    @Test void nativeContextSupplementKeepsFrozenGroupsPendingOnlyMeteringAndTheReviewedHumanRoot(){
        ObjectNode reading=DraftReferenceSupplementCompatibilityTest.source(false);Map<String,Object> base=DraftReferenceSupplementCompatibilityTest.base(reading);String humanBefore=JsonUtils.write(nodes(base).get(0));DraftAutomaticDiscovery.Plan plan=DraftAutomaticDiscovery.plan(Collections.singletonList(reading),base);Map<String,Object> manifest=DraftReferenceSupplementCompatibilityTest.manifest(plan);List<Map<String,Object>> frozen=DraftReferenceSupplementCompatibilityTest.maps(manifest.get("groups"));assertEquals(3,frozen.size());assertEquals(2,DraftAutomaticDiscovery.planGroups(plan).size(),"The current definition route would otherwise regroup the original work");
        String completed=DraftReferenceSupplementCompatibilityTest.task(plan,"domestic-new");items.deleteAll(items.findByRunIdOrderByTaskOrderAsc(id));items.flush();int order=0;for(Map<String,Object> task:plan.tasks()){boolean done=completed.equals(task.get("taskId"));Map<String,Object> receipt=done?new LinkedHashMap<>(task):null;if(done)receipt.putAll(obj("status","partial","nodes",Collections.emptyList(),"requirements",Collections.emptyList(),"issues",Collections.singletonList(obj("reason","historic-review")),"modelCalls",0));item(task,order++,done?"DONE":"PENDING",receipt);}for(Map<String,Object> group:frozen){boolean done=list(group.get("taskIds")).contains(completed);Map<String,Object> receipt=done?new LinkedHashMap<>(group):null;if(done)receipt.putAll(obj("status","partial","rawResponse","ORIGINAL_RAW_MUST_NOT_CHANGE","modelCalls",24,"stopReasons",Collections.singletonList("historic-stop")));DraftAutomationItem stored=item(group,order++,done?"DONE":"PENDING",receipt);if(done){oldGroup=stored;oldRaw=stored.getReceiptJson();}}
        manifest.put("firstProbeFailure",obj("taskId",oldGroup.getTaskId(),"reasons",Collections.singletonList("historic-stop")));DraftAutomationRun run=runs.findById(id).orElseThrow(AssertionError::new);run.setManifestJson(JsonUtils.write(manifest));runs.saveAndFlush(run);Instant created=run.getCreatedAt();Set<String> seen=Collections.synchronizedSet(new HashSet<>());
        when(graphs.automationInput(eq(project),isNull(),eq("saved-result"),isNull(),anyList())).thenAnswer(call->{((List<JsonNode>)call.getArgument(4)).add(reading);return base;});
        when(ai.complete(anyString(),anyString())).thenAnswer(call->{JsonNode packet=JsonUtils.parse(call.getArgument(1));assertEquals(1,packet.path("instructions").size(),"The dispatcher must use the original singleton group, not the fresh combined bucket");JsonNode root=packet.path("knownRoots").path(0),owner=packet.path("instructions").path(0);String alias=root.path("id").asText();assertTrue(Arrays.asList("domesticBlocks","electronicTendering").contains(alias));assertEquals(owner.path("sourceTaskId"),root.path("sourceTaskIds").path(0));if("electronicTendering".equals(alias))assertFalse(root.path("rulePatchAllowed").asBoolean(true),"New native context cannot grant rule patch authority over the reviewed/manual root");seen.add(alias);return JsonUtils.write(obj("nodes",Collections.emptyList(),"requirements",Collections.emptyList(),"scopeRules",Collections.singletonList(obj("id","current_check","sourceTaskId",owner.path("sourceTaskId").asText(),"scopeId",owner.path("scopeObligationIds").path(0).asText(),"when",obj("mode","all","clauses",Collections.singletonList(obj("inputId",alias,"operator","known"))),"action","check")),"taskOutcomes",Collections.singletonList(obj("sourceTaskId",owner.path("sourceTaskId").asText(),"status","unresolved","reason","Current treatment remains under review.")),"notes",Collections.emptyList()));});
        service.resume(project,id,null,"saved-result");Map<String,Object> result=await();assertEquals("continued-result",result.get("resultRevisionId"));verify(ai,times(2)).complete(anyString(),anyString());assertEquals(new HashSet<>(Arrays.asList("domesticBlocks","electronicTendering")),seen);assertEquals(oldRaw,items.findById(oldGroup.getId()).orElseThrow(AssertionError::new).getReceiptJson());DraftAutomationRun saved=runs.findById(id).orElseThrow(AssertionError::new);assertEquals(created,saved.getCreatedAt());assertEquals(JsonUtils.mapper().valueToTree(frozen),JsonUtils.parse(saved.getManifestJson()).path("groups"));assertEquals("historic-stop",JsonUtils.parse(saved.getManifestJson()).path("firstProbeFailure").path("reasons").path(0).asText());
        int charged=0;for(DraftAutomationItem item:items.findByRunIdOrderByTaskOrderAsc(id))if(item.getReceiptJson()!=null)charged+=JsonUtils.parse(item.getReceiptJson()).path("modelCalls").asInt();assertEquals(26,charged,"The original 24 calls remain charged and only two original pending groups are sent");ArgumentCaptor<Map<String,Object>> written=ArgumentCaptor.forClass(Map.class);verify(graphs).save(eq(project),written.capture(),isNull(),eq("saved-result"),eq(true));Map<String,Object> retained=nodes(written.getValue()).stream().filter(node->"electronicTendering".equals(map(node.get("catalogAlignment")).get("baselineKey"))).findFirst().orElseThrow(AssertionError::new);assertEquals(humanBefore,JsonUtils.write(retained));assertEquals(humanBefore,JsonUtils.write(nodes(base).get(0)));
    }

    @Test void incompatibleSavedPreflightSendsNothingAndCanResumeAfterCompatibleSettingsReturn(){
        DraftAutomationRun run=runs.findById(id).orElseThrow(AssertionError::new);Map<String,Object> manifest=JsonUtils.readMap(run.getManifestJson());manifest.put("concurrency",2);map(manifest.get("plan")).remove("sourceIds");List<Object> pending=new ArrayList<>();Map<String,String> states=new LinkedHashMap<>();for(DraftAutomationItem item:items.findByRunIdOrderByTaskOrderAsc(id)){states.put(item.getTaskId(),item.getStatus());if("PENDING".equals(item.getStatus()))pending.add(item.getTaskId());}manifest.put("continuation",obj("baseResultRevisionId","saved-result","expectedCurrentRevisionId",null,"expectedDraftRevisionId","saved-result","taskIds",pending,"startedAt",Instant.now().toString()));run.setManifestJson(JsonUtils.write(manifest));runs.saveAndFlush(run);String before=run.getManifestJson();Instant created=run.getCreatedAt();
        service.resume(project,id,null,"saved-result");Map<String,Object> rejected=await();assertEquals("PARTIAL",rejected.get("status"));assertEquals("READY_FOR_REVIEW",rejected.get("phase"));assertEquals("saved-result",rejected.get("resultRevisionId"));assertTrue(String.valueOf(rejected.get("message")).contains("execution/concurrency"));assertEquals(true,rejected.get("canContinueSavedGroups"));verifyNoInteractions(ai);verify(graphs,never()).save(eq(project),anyMap(),isNull(),eq("saved-result"),eq(true));DraftAutomationRun unchanged=runs.findById(id).orElseThrow(AssertionError::new);assertEquals(JsonUtils.parse(before),JsonUtils.parse(unchanged.getManifestJson()));assertEquals(created,unchanged.getCreatedAt());assertEquals("saved-result",heads.findById(project).orElseThrow(AssertionError::new).getDraftRevisionId());assertEquals(oldRaw,items.findById(oldGroup.getId()).orElseThrow(AssertionError::new).getReceiptJson());for(DraftAutomationItem item:items.findByRunIdOrderByTaskOrderAsc(id))assertEquals(states.get(item.getTaskId()),item.getStatus());assertEquals(1,JsonUtils.parse(items.findById(oldGroup.getId()).orElseThrow(AssertionError::new).getReceiptJson()).path("modelCalls").asInt());
        service.groupConcurrency(2);service.resume(project,id,null,"saved-result");Map<String,Object> continued=await();assertEquals("continued-result",continued.get("resultRevisionId"));verify(ai,times(1)).complete(anyString(),anyString());assertEquals(oldRaw,items.findById(oldGroup.getId()).orElseThrow(AssertionError::new).getReceiptJson());assertEquals(created,runs.findById(id).orElseThrow(AssertionError::new).getCreatedAt());
    }

    @Test void savedContinuationRejectsOversizedCurrentPacketBeforePendingOrBudgetChanges(){
        ObjectNode large=source("2");String quote=String.join("",Collections.nCopies(45000,"x"));((ObjectNode)large.path("sourceMembers").path(0).path("textObservation")).put("text",quote);((ObjectNode)large.path("guidanceNotes").path(0)).put("text",quote);((ObjectNode)large.path("guidanceNotes").path(0).path("memberRanges").path(0)).put("end",quote.length());
        List<JsonNode> readings=Arrays.asList(source("1"),large);DraftAutomaticDiscovery.Plan plan=DraftAutomaticDiscovery.plan(readings);List<Map<String,Object>> groups=DraftAutomaticDiscovery.planGroups(plan);Map<String,Object> pending=groups.get(1);assertEquals("ready",pending.get("status"),"The frozen source-only bucket fits; the complete current request must still be checked");
        Map<String,Object> blocked=DraftAutomaticDiscovery.processGroup((system,user)->{throw new AssertionError("An oversized packet must not dispatch");},plan,pending);assertEquals("before_dispatch",blocked.get("failureStage"));assertEquals(0,blocked.get("modelCalls"));assertTrue(String.valueOf(blocked.get("systemPrompt")).length()+String.valueOf(blocked.get("userPrompt")).length()>DraftDiscoveryGroups.MAX_PACKET_CHARS);
        for(DraftAutomationItem item:items.findByRunIdOrderByTaskOrderAsc(id))if("PENDING".equals(item.getStatus()))items.delete(item);items.flush();item(plan.tasks().get(1),1,"PENDING",null);item(pending,3,"PENDING",null);
        DraftAutomationRun run=runs.findById(id).orElseThrow(AssertionError::new);Map<String,Object> manifest=JsonUtils.readMap(run.getManifestJson());manifest.put("plan",plan.descriptor());manifest.put("groups",groups);List<String> pendingIds=new ArrayList<>();Map<String,String> states=new LinkedHashMap<>();for(DraftAutomationItem item:items.findByRunIdOrderByTaskOrderAsc(id)){states.put(item.getTaskId(),item.getStatus());if("PENDING".equals(item.getStatus()))pendingIds.add(item.getTaskId());}manifest.put("continuation",obj("baseResultRevisionId","saved-result","expectedCurrentRevisionId",null,"expectedDraftRevisionId","saved-result","taskIds",pendingIds,"startedAt",Instant.now().toString()));run.setManifestJson(JsonUtils.write(manifest));runs.saveAndFlush(run);String before=run.getManifestJson();Instant created=run.getCreatedAt();
        when(graphs.automationInput(eq(project),isNull(),eq("saved-result"),isNull(),anyList())).thenAnswer(call->{((List<JsonNode>)call.getArgument(4)).addAll(readings);return obj("graph",obj("variables",new ArrayList<>(),"events",new ArrayList<>()),"sources",new ArrayList<>());});
        service.resume(project,id,null,"saved-result");Map<String,Object> rejected=await();assertEquals("PARTIAL",rejected.get("status"));assertEquals("READY_FOR_REVIEW",rejected.get("phase"));assertEquals("saved-result",rejected.get("resultRevisionId"));assertTrue(String.valueOf(rejected.get("message")).contains("group_source_context_exceeds_packet_budget"));assertEquals(true,rejected.get("canContinueSavedGroups"));verifyNoInteractions(ai);verify(graphs,never()).save(eq(project),anyMap(),isNull(),eq("saved-result"),eq(true));DraftAutomationRun unchanged=runs.findById(id).orElseThrow(AssertionError::new);assertEquals(JsonUtils.parse(before),JsonUtils.parse(unchanged.getManifestJson()));assertEquals(created,unchanged.getCreatedAt());assertEquals("saved-result",heads.findById(project).orElseThrow(AssertionError::new).getDraftRevisionId());assertEquals(oldRaw,items.findById(oldGroup.getId()).orElseThrow(AssertionError::new).getReceiptJson());for(DraftAutomationItem item:items.findByRunIdOrderByTaskOrderAsc(id))assertEquals(states.get(item.getTaskId()),item.getStatus(),item.getTaskId());assertEquals(1,JsonUtils.parse(oldRaw).path("modelCalls").asInt());
        manifest.remove("continuation");unchanged.setManifestJson(JsonUtils.write(manifest));runs.saveAndFlush(unchanged);String executionBefore=unchanged.getManifestJson();service.resume(project,id,null,"saved-result");Map<String,Object> freshRejected=await();assertEquals("PARTIAL",freshRejected.get("status"));assertEquals("saved-result",freshRejected.get("resultRevisionId"));assertEquals(true,freshRejected.get("canContinueSavedGroups"));Map<String,Object> fresh=JsonUtils.readMap(runs.findById(id).orElseThrow(AssertionError::new).getManifestJson()),cycle=map(fresh.remove("continuation"));assertEquals(JsonUtils.parse(executionBefore),JsonUtils.mapper().valueToTree(fresh),"Only resume's ordinary cycle initialization may be added; the execution manifest must not change");assertEquals("saved-result",cycle.get("baseResultRevisionId"));assertEquals(pendingIds,list(cycle.get("taskIds")));assertFalse(text(cycle.get("startedAt")).isEmpty());verifyNoInteractions(ai);verify(graphs,never()).save(eq(project),anyMap(),isNull(),eq("saved-result"),eq(true));assertEquals(created,runs.findById(id).orElseThrow(AssertionError::new).getCreatedAt());assertEquals("saved-result",heads.findById(project).orElseThrow(AssertionError::new).getDraftRevisionId());assertEquals(oldRaw,items.findById(oldGroup.getId()).orElseThrow(AssertionError::new).getReceiptJson());for(DraftAutomationItem item:items.findByRunIdOrderByTaskOrderAsc(id))assertEquals(states.get(item.getTaskId()),item.getStatus(),item.getTaskId());
    }

    private DraftAutomationItem item(Map<String,Object> task,int order,String status,Map<String,Object> receipt){DraftAutomationItem row=new DraftAutomationItem();row.setId(UUID.randomUUID().toString());row.setRunId(id);row.setTaskId(text(task.get("taskId")));row.setTaskOrder(order);row.setTaskJson(JsonUtils.write(task));row.setStatus(status);if(receipt!=null)row.setReceiptJson(JsonUtils.write(receipt));return items.saveAndFlush(row);}
    private Map<String,Object> await(){long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(5);Map<String,Object> result;do{result=service.get(project,id);if(!Arrays.asList("QUEUED","RUNNING").contains(result.get("status")))return result;try{Thread.sleep(10);}catch(InterruptedException e){throw new AssertionError(e);}}while(System.nanoTime()<deadline);throw new AssertionError("Synthetic worker did not finish");}
    private static ObjectNode source(String id){String quote="A synthetic source reminder.",sha=String.join("",Collections.nCopies(64,"a"));ObjectNode source=JsonUtils.mapper().createObjectNode().put("id",id).put("sourceSha256",sha).put("evidenceStatus","bound").put("format","docx");ObjectNode member=source.putArray("sourceMembers").addObject().put("id","m"+id).put("identityStatus","source_bound");member.putObject("sourcePosition").put("sourceSha256",sha).put("partName","word/document.xml").put("nodePath","/p"+id);member.putObject("textObservation").put("text",quote);ObjectNode note=source.putArray("guidanceNotes").addObject().put("id","g"+id).put("text",quote).put("captureComplete",true);note.putArray("orderedMemberIds").add("m"+id);note.putArray("memberRanges").addObject().put("memberId","m"+id).put("channel","text").put("start",0).put("end",quote.length());return source;}
}
